1131	fn receipt_lines(sections: &[ReceiptSection]) -> Vec<Line<'_>> {
1132	    let heading = Style::default()
1133	        .fg(Color::White)
1134	        .add_modifier(Modifier::BOLD);
1135	    let muted = Style::default().fg(MUTED);
1136	    let mut lines = Vec::new();
1137	    for (index, section) in sections.iter().enumerate() {
1138	        if index > 0 {
1139	            lines.push(Line::default());
1140	        }
1141	        lines.push(Line::from(Span::styled(one_line(&section.title), heading)));
1142	        for (label, value) in &section.rows {
1143	            lines.push(Line::from(vec![
1144	                Span::styled(format!("  {:<15}", one_line(label)), muted),
1145	                Span::styled(one_line(value), Style::default().fg(verdict_color(value))),
1146	            ]));
1147	        }
1148	        if let Some(note) = &section.note {
1149	            lines.push(Line::from(Span::styled(
1150	                format!("  {}", one_line(note)),
1151	                muted,
1152	            )));
1153	        }
1154	    }
1155	    lines
1156	}
