1158	/// Colours outcome words in the receipt; every other value stays white.
1159	fn verdict_color(value: &str) -> Color {
1160	    match value {
1161	        "PASSED" | "VERIFIED" | "COMPLETED" | "success" => Color::Green,
1162	        "FAILED" | "INVALIDATED" | "NOT_ESTABLISHED" | "INTERRUPTED" | "BLOCKED"
1163	        | "LIMIT_REACHED" | "failure" => Color::Red,
1164	        "UNVERIFIED" | "REGRESSION_FREE" => Color::Yellow,
1165	        _ => Color::White,
1166	    }
1167	}
