1169	/// Draws the composer rows that hold the cursor and places the terminal cursor while the operator is typing.
1170	fn render_composer(frame: &mut Frame, area: Rect, state: &LiveState, layout: &ComposerLayout) {
1171	    let prompt = Style::default().fg(ACCENT).add_modifier(Modifier::BOLD);
1172	    let height = usize::from(area.height);
1173	    let top = (layout.cursor.0 + 1).saturating_sub(height);
1174	    let lines: Vec<Line> = layout
1175	        .rows
1176	        .iter()
1177	        .enumerate()
1178	        .skip(top)
1179	        .take(height)
1180	        .map(|(index, row)| {
1181	            Line::from(vec![
1182	                Span::styled(if index == 0 { "› " } else { "  " }, prompt),
1183	                Span::raw(row.as_str()),
1184	            ])
1185	        })
1186	        .collect();
1187	    frame.render_widget(Paragraph::new(lines), area);
1188	    if state.composer.is_empty() && state.overlay.is_none() && state.focus == Focus::Composer && state.link == Link::Ready && !state.closing {
1189	        let room = usize::from(area.width.saturating_sub(PREFIX_WIDTH));
1190	        let placeholder = if state.session.busy {
1191	            if room < "type to steer the running turn · esc cancels it".chars().count() {
1192	                "type to steer · esc cancels"
1193	            } else {
1194	                "type to steer the running turn · esc cancels it"
1195	            }
1196	        } else if room < "ask Nexus · / for commands · ? for keys".chars().count() {
1197	            "ask Nexus · / commands · ? keys"
1198	        } else {
1199	            "ask Nexus · / for commands · ? for keys"
1200	        };
1201	        let placeholder: Cow<str> = if placeholder.chars().count() > room && room > 1 {
1202	            Cow::Owned(format!("{}…", placeholder.chars().take(room - 1).collect::<String>()))
1203	        } else {
1204	            Cow::Borrowed(placeholder)
1205	        };
1206	        frame.render_widget(
1207	            Paragraph::new(Span::styled(placeholder, Style::default().fg(MUTED).add_modifier(Modifier::DIM))),
1208	            Rect { x: area.x + PREFIX_WIDTH, width: area.width.saturating_sub(PREFIX_WIDTH), height: 1, ..area },
1209	        );
1210	    }
1211	    let typing = !matches!(state.link, Link::Crashed { .. })
1212	        && state.overlay.is_none()
1213	        && state.focus == Focus::Composer
1214	        && !state.closing;
1215	    if typing && let Ok(row) = u16::try_from(layout.cursor.0 - top) {
1216	        frame.set_cursor_position((area.x + PREFIX_WIDTH + layout.cursor.1, area.y + row));
1217	    }
1218	}
