1220	/// The status bar: identity only (workspace, branch, model, mode). Activity is shown once, on the composer line.
1221	/// Segments are dropped from the least important when the terminal is narrow.
1222	fn render_status(frame: &mut Frame, area: Rect, state: &LiveState) {
1223	    let session = &state.session;
1224	    let muted = Style::default().fg(MUTED);
1225	    let surface = Style::default().bg(SURFACE);
1226	    let badge = Span::styled(" NEXUS ", Style::default().fg(Color::Black).bg(ACCENT).add_modifier(Modifier::BOLD));
1227	    let mut spans = vec![badge];
1228	    match &state.link {
1229	        _ if state.connecting() => spans.push(Span::styled("  connecting to the agent…", muted)),
1230	        Link::Crashed { .. } => spans.push(Span::styled("  agent stopped — not running", Style::default().fg(Color::Red).add_modifier(Modifier::BOLD))),
1231	        _ => {
1232	            // (priority, spans): lower numbers are kept first.
1233	            let mut segments: Vec<(u8, Vec<Span>)> = vec![(0, vec![Span::styled(format!("  {}", session.workspace_name), Style::default().fg(Color::White).add_modifier(Modifier::BOLD))])];
1234	            if let Some(branch) = &session.branch {
1235	                let mut branch_spans = vec![Span::styled(format!("  ⎇ {branch}"), muted)];
1236	                if session.dirty > 0 {
1237	                    branch_spans.push(Span::styled(format!(" ●{} changed", session.dirty), Style::default().fg(Color::Yellow)));
1238	                }
1239	                segments.push((3, branch_spans));
1240	            }
1241	            segments.push((2, vec![Span::styled("  model ", muted), Span::styled(session.model.clone(), Style::default().fg(Color::White))]));
1242	            // The session id (what /resume takes) is kept only when there is room for it.
1243	            if let Some(id) = &session.session_id {
1244	                segments.push((5, vec![Span::styled(format!("  {id}"), muted)]));
1245	            }
1246	            // The mode is kept at every width: whether changes need approval is never hidden.
1247	            if let Some(posture) = &session.posture {
1248	                let mode_color = if posture.mode == "review" { Color::Yellow } else { Color::White };
1249	                segments.push((1, vec![Span::styled(format!("  mode: {}", posture.mode), Style::default().fg(mode_color))]));
1250	                let trust_str = if posture.trusted { "trusted" } else { "untrusted" };
1251	                segments.push((4, vec![
1252	                    Span::styled(format!(" · sandbox: {}", posture.sandbox), muted),
1253	                    Span::styled(format!(" · workspace: {trust_str}"), muted),
1254	                ]));
1255	            } else if session.mode == "review" {
1256	                segments.push((1, vec![Span::styled("  review mode", Style::default().fg(Color::Yellow))]));
1257	            } else {
1258	                segments.push((1, vec![Span::styled(format!("  {}", session.mode), muted)]));
1259	            }
1260	            // Read-only is a safety fact (kept at every width); context use and endpoint kind go first when narrow.
1261	            if session.read_only == Some(true) {
1262	                segments.push((1, vec![Span::styled("  read-only", Style::default().fg(Color::Yellow))]));
1263	            }
1264	            if let (Some(used), Some(limit)) = (session.context_tokens, session.context_limit) {
1265	                segments.push((6, vec![Span::styled(format!("  context {used}/{limit}"), muted)]));
